import{_ as p,o as e,c as o,a5 as n}from"./chunks/framework.Cooo9kuv.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"457-1-批量删除pdf中与模板页面自定义相似度的页面","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["删除相似页面","根据模板相似度删除pdf页面"]},"headers":[{"level":3,"title":"适用系统环境","slug":"适用系统环境","link":"#适用系统环境","children":[]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]}],"relativePath":"md/PDF批处理/457-1-批量删除pdf中与模板页面自定义相似度的页面.md","filePath":"md/PDF批处理/457-1-批量删除pdf中与模板页面自定义相似度的页面.md"}'),a={name:"md/PDF批处理/457-1-批量删除pdf中与模板页面自定义相似度的页面.md"};function r(s,t,_,d,l,f){return e(),o("div",null,[...t[0]||(t[0]=[n('<p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250416201351174480563110355.png" alt=""></p><p>批量删除与模板pdf页面<strong>具有一定相似度的</strong>目标pdf中的页面</p><p>根据模板pdf页面，在目标pdf文件中找到与模板页面<strong>具有一定相似度的</strong>页面并删除该页面</p><p>比如A文件夹下有很多pdf文件，同时有子文件夹，子文件夹下也有PDF文件</p><p><strong>创建一个文件夹B用来放模板pdf，模板pdf页面为目标pdf中提取的某个页面</strong></p><p>在程序中选择A文件夹路径作为需要批量处理的文件夹路径</p><p><strong>选择B文件夹作为模板文件夹</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250318122825174227210524350.png" alt="457-批量删除pdf中与模板页面完全一样的页面"></p><p>运行程序后，会将A文件夹下所有pdf中与模板<strong>具有一定相似度的页面</strong>都删除掉，会在A文件夹下自动创建一个 processed_file 文件夹，A文件夹下所有文件处理后都放在该文件夹下，结构与原A文件夹结构一样。</p><h3 id="适用系统环境" tabindex="-1">适用系统环境 <a class="header-anchor" href="#适用系统环境" aria-label="Permalink to &quot;适用系统环境&quot;">​</a></h3><p>win7及以上64位操作系统</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>程序初始打开稍慢，耐心等待即可</p><p>pdf页数及大小越大速度越慢，运行速度取决于页面多少和pdf整体文件大小</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1668.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1668.html</a></p>',16)])])}const c=p(a,[["render",r]]);export{i as __pageData,c as default};
